#ifndef NX300M_PREVIEW_RGB_H
#define NX300M_PREVIEW_RGB_H
#include <stdint.h>
#include <stddef.h>
#include "nx300m_lut18.h"
/* Camera-neutral preview adapter. RGB888 input/output, stride in BYTES.
 * This is NOT yet connected to Samsung NX300M ISP/liveview image memory.
 * LUT is generated by nx_film_lut_for_menu() and shared with still JPEG path.
 * LUT accepts normalized linear-light RGB 12-bit samples.
 */
typedef struct {
    uint16_t decode_srgb[256];
    uint8_t encode_srgb[4096];
    int compare_original;
} nx_preview_processor;
int nx_preview_init(nx_preview_processor *p);
int nx_preview_filter_rgb888(const nx_preview_processor *p,const nx_rgb12 *lut,
    const unsigned char *input,size_t input_stride,unsigned char *output,size_t output_stride,
    unsigned width,unsigned height);
#endif
